 1	/* ============================================================
 2	   utils.js — Shared utility functions
 3	   Section 4 of the MCP Server Dashboard SPA
 4	   ============================================================ */
 5	
 6	function escapeHtml(str) {
 7	  if (str === null || str === undefined) return '';
 8	  return String(str)
 9	    .replace(/&/g, '&amp;')
10	    .replace(/</g, '&lt;')
11	    .replace(/>/g, '&gt;')
12	    .replace(/"/g, '&quot;');
13	}
14	
15	function formatDate(isoString) {
16	  if (!isoString) return '—';
17	  try {
18	    var d = new Date(isoString);
19	    if (isNaN(d.getTime())) return escapeHtml(isoString);
20	    var pad = function (n) { return String(n).padStart(2, '0'); };
21	    var timeStr = pad(d.getHours()) + ':' + pad(d.getMinutes());
22	
23	    var now = new Date();
24	    // Strip times for day-boundary comparisons
25	    var today    = new Date(now.getFullYear(),    now.getMonth(),    now.getDate());
26	    var itemDay  = new Date(d.getFullYear(),      d.getMonth(),      d.getDate());
27	    var diffDays = Math.round((today - itemDay) / 86400000);
28	
29	    if (diffDays === 0) return 'Today, ' + timeStr;
30	    if (diffDays === 1) return 'Yesterday, ' + timeStr;
31	    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
32	    if (diffDays < 7)  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d.getDay()] + ', ' + d.getDate() + ' ' + months[d.getMonth()] + ', ' + timeStr;
33	
34	    // Older: show short date like "12 Feb 2026, 16:41"
35	    return d.getDate() + ' ' + months[d.getMonth()] + ' ' + d.getFullYear() + ', ' + timeStr;
36	  } catch (_) {
37	    return escapeHtml(isoString);
38	  }
39	}
40	
41	function statusBadge(status) {
42	  if (!status) return '';
43	  var cls = 'badge badge-' + status.toLowerCase().replace(/_/g, '-');
44	  return '<span class="' + cls + '">' + escapeHtml(status) + '</span>';
45	}
46	
47	// Cache of slug → display name, populated by views that fetch project data.
48	// breadcrumb().project() reads from here automatically.
49	var ProjectNameCache = (function () {
50	  var _cache = {};
51	  return {
52	    set: function (slug, name) {
53	      if (slug && name && name.trim()) _cache[slug] = name.trim();
54	    },
55	    get: function (slug) {
56	      return _cache[slug] || slug;
57	    },
58	  };
59	}());
60	
61	function breadcrumb() {
62	  var segments = [];
63	  var api = {
64	    projects: function () {
65	      segments.push({ label: 'Projects', href: '#/' });
66	      return api;
67	    },
68	    project: function (repo, slug) {
69	      segments.push({ label: ProjectNameCache.get(slug), href: '#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) });
70	      return api;
71	    },
72	    leaf: function (label) {
73	      segments.push({ label: label });
74	      return api;
75	    },
76	    leafSpan: function (label, id) {
77	      segments.push({ label: label, id: id });
78	      return api;
79	    },
80	    html: function () {
81	      return '<p class="breadcrumb">' +
82	        segments.map(function (s) {
83	          if (s.href) return '<a href="' + s.href + '">' + escapeHtml(s.label) + '</a>';
84	          if (s.id)   return '<span id="' + escapeHtml(s.id) + '">' + escapeHtml(s.label) + '</span>';
85	          return escapeHtml(s.label);
86	        }).join(' / ') +
87	        '</p>';
88	    }
89	  };
90	  return api;
91	}
92	
93	function showLoading(container) {
94	  container.innerHTML = '<div class="loading">Loading…</div>';
95	}
96	
97	function showError(container, message) {
98	  container.innerHTML = '<div class="error-banner">' + escapeHtml(message) + '</div>';
99	}

 1	/* ============================================================
 2	   router.js — Router module
 3	   Section 3 of the MCP Server Dashboard SPA
 4	   ============================================================ */
 5	
 6	var Router = (function () {
 7	  var _activeInterval = null;
 8	
 9	  function clearPolling() {
10	    if (_activeInterval !== null) {
11	      clearInterval(_activeInterval);
12	      _activeInterval = null;
13	    }
14	  }
15	
16	  function setPolling(intervalFn, delayMs) {
17	    clearPolling();
18	    _activeInterval = setInterval(intervalFn, delayMs);
19	  }
20	
21	  function updateNavActive(path) {
22	    var navLinks = document.querySelectorAll('header nav a');
23	    navLinks.forEach(function (link) {
24	      var href = link.getAttribute('href') || '';
25	      var linkPath = href.replace(/^#/, '') || '/';
26	      link.classList.toggle('active', linkPath === path || (path === '' && linkPath === '/'));
27	    });
28	  }
29	
30	  function dispatch(hash) {
31	    clearPolling();
32	    var path = (hash || '').replace(/^#/, '') || '/';
33	    var app = document.getElementById('app');
34	    if (!app) return;
35	
36	    updateNavActive(path);
37	
38	    if (path === '/' || path === '') {
39	      renderProjectList(app);
40	      return;
41	    }
42	
43	    var planMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)\/plan$/);
44	    if (planMatch) {
45	      renderPlan(app, decodeURIComponent(planMatch[1]), decodeURIComponent(planMatch[2]));
46	      return;
47	    }
48	
49	    var synthesisMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)\/synthesis$/);
50	    if (synthesisMatch) {
51	      renderSynthesis(app, decodeURIComponent(synthesisMatch[1]), decodeURIComponent(synthesisMatch[2]));
52	      return;
53	    }
54	
55	    var projectMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)$/);
56	    if (projectMatch) {
57	      renderProjectDetail(app, decodeURIComponent(projectMatch[1]), decodeURIComponent(projectMatch[2]));
58	      return;
59	    }
60	
61	    var wpMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)\/wp\/([^/]+)$/);
62	    if (wpMatch) {
63	      renderWorkPackageDetail(app, decodeURIComponent(wpMatch[1]), decodeURIComponent(wpMatch[2]), decodeURIComponent(wpMatch[3]));
64	      return;
65	    }
66	
67	    var runLogMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)\/runs\/([^/]+)$/);
68	    if (runLogMatch) {
69	      renderRunLog(app, decodeURIComponent(runLogMatch[1]), decodeURIComponent(runLogMatch[2]), decodeURIComponent(runLogMatch[3]));
70	      return;
71	    }
72	
73	    /* ── Named singleton routes ──────────────────────────────── */
74	    if (path === '/config') {
75	      renderConfig(app);
76	      return;
77	    }
78	
79	    if (path === '/insights') {
80	      renderInsights(app);
81	      return;
82	    }
83	
84	    if (path === '/knowledge') {
85	      renderKnowledge(app);
86	      return;
87	    }
88	
89	    if (path === '/orchestrator') {
90	      renderOrchestrator(app);
91	      return;
92	    }
93	
94	    app.innerHTML = '<p class="error-banner">Page not found: ' + escapeHtml(path) + '</p>';
95	  }
96	
97	  function navigate(hash) {
98	    window.location.hash = hash;
99	  }

